console.log(policzPole(4)); // 16 - dziala, mimo ze definicja jest ponizej

function policzPole(bok) {
  return bok * bok;
}

// gdyby wywolac policzObwod(5) PRZED ta linia, JavaScript zglosilby blad
// (ReferenceError zwiazany z Temporal Dead Zone dla const, pelne
// wyjasnienie w lekcji 3) - w odroznieniu od zwyklej deklaracji funkcji,
// function expression NIE jest dostepna przed swoja linia kodu

const policzObwod = function (bok) {
  return bok * 4;
};

console.log(policzObwod(5)); // 20 - dziala PO tej linii

// console.log(x); // ReferenceError: Cannot access 'x' before initialization
