function sprawdzWartosc() {
  console.log(typeof znaleziono); // "undefined" - juz zarezerwowane miejsce

  if (true) {
    var znaleziono = true;
  }

  console.log(znaleziono); // true
}

sprawdzWartosc();

function jestParzysta(n) {
  if (n === 0) return true;
  return jestNieparzysta(n - 1);
}

function jestNieparzysta(n) {
  if (n === 0) return false;
  return jestParzysta(n - 1);
}

console.log(jestParzysta(4)); // true
console.log(jestNieparzysta(4)); // false

var status;
var status;
var status = "gotowy";

console.log(status); // "gotowy"
// hoisting rezerwuje JEDNO miejsce dla 'status', niezaleznie od tego,
// ile razy slowo 'var status' pojawia sie w tym samym zasiegu -
// kolejne 'var status' to nie nowe zmienne, tylko te sama, powtorzona deklaracja

function pobierzUstawienie(domyslna) {
  if (typeof ustawienie === "undefined") {
    var ustawienie = domyslna;
  }
  return ustawienie;
}

console.log(pobierzUstawienie("ciemny")); // "ciemny"

