function przetworzDane(dane) {
  if (!walidujDlugosc(dane)) {
    return "brak danych";
  }
  return "przetworzono " + dane.length + " elementow";
}

console.log(przetworzDane([1, 2, 3])); // "przetworzono 3 elementow"

function walidujDlugosc(tablica) {
  return tablica.length > 0;
}

try {
  console.log(a()); // "deklaracja" - dziala
} catch (e) {
  console.log("a() blad:", e.name);
}

try {
  console.log(b()); // rzuci blad
} catch (e) {
  console.log("b() blad:", e.name); // "ReferenceError"
}

function a() {
  return "deklaracja";
}

const b = function () {
  return "wyrazenie";
};
